a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_coxboost.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("CoxBoost",quietly=TRUE))stop("Install CoxBoost");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);x<-as.matrix(tr[,v,drop=FALSE]);xv<-as.matrix(va[,v,drop=FALSE]);set.seed(seed);pen<-CoxBoost::optimCoxBoostPenalty(tr$Time,tr$Event,x,start.penalty=200,trace=FALSE);set.seed(seed);cv<-CoxBoost::cv.CoxBoost(tr$Time,tr$Event,x,maxstepno=200,K=10,type="verweij",penalty=pen$penalty);fit<-CoxBoost::CoxBoost(tr$Time,tr$Event,x,stepno=cv$optimal.step,penalty=pen$penalty);lp<-function(z)as.numeric(predict(fit,newdata=z,newtime=rep(1,nrow(z)),newstatus=rep(1,nrow(z)),type="lp"));write.csv(data.frame(Time=tr$Time,Event=tr$Event,CoxBoost=lp(x)),file.path(out,"development_coxboost_predictions.csv"),row.names=FALSE);write.csv(data.frame(Time=va$Time,Event=va$Event,CoxBoost=lp(xv)),file.path(out,"validation_coxboost_predictions.csv"),row.names=FALSE);saveRDS(list(model=fit,penalty=pen,cv=cv,predictors=v),file.path(out,"coxboost_model.rds"))
